// t02: purchases and sales day books, simple and columnar (credit purchases and sales of goods only, trade discount
// deducted, totals and posting). Imagined firms; every book is generated by dayBook() and asserted. No GST.
import { mcq, ar, tf, fb, short, long } from './lib.mjs';
import { same, check, sum, inr, rs, mdTable, dayBook, Ledger, postMd, T } from './books.mjs';
import { QQ, numQ } from './qq.mjs';

// ================================================================ multiple choice
QQ('m_pb_which', mcq({
  t: 2, d: 2, c: 'understanding',
  stem: 'Gaya Furnishers, an imagined furniture dealer, makes four transactions in a month. Which one is entered in its purchases book?',
  opts: ['Chairs bought on credit from a manufacturer for resale', 'Chairs bought from a manufacturer for cash', 'A typewriter for the office bought on credit', 'Chairs sent back to the manufacturer'],
  sol: 'Only credit purchases of goods the firm deals in go to the purchases book. The cash purchase belongs to the cash book, the typewriter is an asset and goes to the journal proper, and the return of chairs is recorded in the purchases return book.',
}));
const NETA = 45000 - Math.round((45000 * 12) / 100);
same(NETA, 39600, 'm_pb_net');
QQ('m_pb_net', mcq({
  t: 2, d: 2, c: 'application',
  stem: 'Latur Steel Traders, an imagined firm, receives an invoice for goods bought on credit at a list price of ₹45,000 less trade discount of 12%. The amount entered in its purchases book is',
  opts: [rs(NETA), rs(45000), rs(5400), rs(50400)],
  sol: `Trade discount = ${inr(45000)} × 12 ÷ 100 = ${inr(5400)}, and net amount = ${inr(45000)} − ${inr(5400)} = ${rs(NETA)}. The ${rs(45000)} ignores the discount, ${rs(5400)} is the discount alone, and ${rs(50400)} adds it instead of deducting it.`,
}));
QQ('m_td_book', mcq({
  t: 2, d: 2, c: 'understanding',
  stem: 'Basti Hardware, an imagined firm, sells goods on credit at a list price of ₹20,000 with a trade discount of 10%. In its sales book',
  opts: ['only the net amount of ₹18,000 is entered, and the discount has no account of its own', '₹20,000 is entered and ₹2,000 is debited to a Trade Discount A/c', '₹20,000 is entered and the discount is shown in the cash book', '₹18,000 is entered and ₹2,000 is credited to a Trade Discount A/c'],
  sol: 'Trade discount is a deduction from the list price made on the invoice itself, so only the net sale is a transaction. It is therefore not debited or credited to any discount account, and the cash book is not involved.',
}));
QQ('m_sb_source', mcq({
  t: 2, d: 1, c: 'recall',
  stem: 'The entry for each credit sale of goods in the sales book of Mandsaur Pulses, an imagined firm, is made from',
  opts: ['the copy of the invoice sent to the customer', 'the debit note received from the customer', 'the pay-in slip of the bank', 'the cash memo of a counter sale'],
  sol: 'The sales book is written from the firm\'s own copy of the invoice. A debit note is a returns document, a pay-in slip is a bank paper, and a cash memo belongs to cash sales.',
}));
QQ('m_columnar_use', mcq({
  t: 2, d: 2, c: 'understanding',
  stem: 'Chhapra Grain Stores, an imagined firm, deals in rice, wheat and maize and wants to know each month how much of each grain it bought on credit. The book best suited to this need is',
  opts: ['a columnar purchases book with a column for each grain', 'a simple purchases book with one amount column', 'a petty cash book with an analysis column for each grain', 'a sales book with a column for each customer'],
  sol: 'A column for each class of goods gives its monthly total directly, and the column totals can be posted to separate purchases accounts. The simple book gives one total only, the petty cash book records small expenses, and the sales book records sales.',
}));
QQ('m_cash_discount', mcq({
  t: 2, d: 4, c: 'analysis',
  stem: 'An invoice received by Nagaon Pumps, an imagined firm, shows goods at ₹30,000 less trade discount 10%, and adds "a further 2% discount if the bill is paid within 15 days". How are these treated in the purchases book?',
  opts: ['Only the trade discount is deducted, so ₹27,000 is entered; the 2% is dealt with when the payment is made', 'Both discounts are deducted, so ₹26,460 is entered', 'Neither is deducted, so ₹30,000 is entered', 'Only the 2% is deducted, so ₹29,400 is entered'],
  sol: `The trade discount is final on the invoice; the extra 2% is a cash discount that depends on prompt payment and is recorded in the cash book when it is earned. Deducting both gives ${rs(26460)}, ignoring both gives ${rs(30000)}, and deducting only the cash discount gives ${rs(29400)}.`,
}));
QQ('m_pb_post', mcq({
  t: 2, d: 2, c: 'understanding',
  stem: 'At the month end, Sehore Seeds, an imagined firm, posts its purchases book to the ledger. The month\'s total is posted to',
  opts: ['the debit of the Purchases A/c, each invoice having been posted to the credit of the supplier\'s account', 'the credit of the Purchases A/c, each invoice having been posted to the debit of the supplier\'s account', 'the debit of the Cash A/c, each invoice having been posted to the credit of the supplier\'s account', 'the credit of the Sales A/c, each invoice having been posted to the debit of the supplier\'s account'],
  sol: 'A credit purchase debits Purchases and credits the supplier, so the book total goes to the debit of Purchases and each invoice to the credit of a supplier. The other options reverse the sides or name a wrong account.',
}));

// ================================================================ assertion-reason
QQ('ar_pb_machinery', ar({
  t: 2, d: 3, c: 'analysis', verdict: 'both-true-explains',
  a: 'A machine bought on credit by Hubli Textiles, an imagined cloth dealer, is not entered in its purchases book.',
  r: 'The purchases book is meant only for credit purchases of the goods in which the firm deals.',
  sol: 'Both are true, and the reason is exactly why the machine is left out: it is an asset, not goods for resale, so the journal proper is used.',
}));
QQ('ar_td_net', ar({
  t: 2, d: 3, c: 'analysis', verdict: 'A-true-R-false',
  a: 'In the purchases book of Bokaro Tools, an imagined firm, an invoice is entered at its price after deducting trade discount.',
  r: 'Trade discount is an expense of the buyer and is debited to a Discount Allowed A/c.',
  sol: 'The assertion is true. The reason is false: trade discount is not recorded in any account, and the discount allowed account relates to cash discount given to debtors.',
}));

// ================================================================ true-false, fill-blank
QQ('tf_chk_columnar', tf({
  t: 2, d: 2, c: 'understanding', ans: true,
  stem: 'In the columnar sales book of Ongole Oils, an imagined firm, the totals of the goods columns added together equal the total of the invoice amount column.',
  sol: 'Each invoice is split among the goods columns and also shown in the total column, so the two grand totals must agree; a mismatch signals an error.',
}));
QQ('tf_sb_cash', tf({
  t: 2, d: 1, c: 'recall', ans: false,
  stem: 'A cloth merchant, Adilabad Fabrics, an imagined firm, records goods sold across the counter for cash in its sales book.',
  sol: 'A cash sale is entered in the cash book. The sales book takes credit sales of goods only.',
}));
QQ('fb_sb_credit', fb({
  t: 2, d: 1, c: 'recall',
  stem: 'The sales book of Pali Plastics, an imagined firm, records only ______ sales of ______ in which the firm deals, and its total is posted to the ______ side of the Sales A/c.',
  acc: [['credit'], ['goods'], ['credit']],
  sol: 'Credit sales of goods are entered, and the total goes to the credit of Sales.',
}));

// ================================================================ numerical
const N1 = dayBook({ kind: 'purchases', entries: [T('1', 'a', 'X', 38000, 15)] });
same(N1.totals.net, 32300, 'n_chk_net');
QQ('n_chk_net', numQ({
  t: 2, d: 2, c: 'application', value: N1.totals.net,
  stem: 'Sikar Ceramics, an imagined firm, buys goods on credit at a list price of ₹38,000 with trade discount of 15%. The amount entered in its purchases book is (in ₹)',
  sol: `Discount = ${inr(38000)} × 15 ÷ 100 = ${inr(5700)}; net = ${inr(38000)} − ${inr(5700)} = ${rs(N1.totals.net)}.`,
}));
const N2 = dayBook({ kind: 'purchases', entries: [T('1', '1', 'A', 20000, 10), T('2', '2', 'B', 15000, 20), T('3', '3', 'A', 9000, 0)] });
same(N2.totals.net, 39000, 'n_pb_total');
QQ('n_pb_total', numQ({
  t: 2, d: 3, c: 'application', value: N2.totals.net,
  stem: 'Barmer Carpets, an imagined firm, bought goods on credit in a month on three invoices: list price ₹20,000 with trade discount 10%, list price ₹15,000 with trade discount 20%, and list price ₹9,000 with no discount. The total of its purchases book for the month is (in ₹)',
  sol: `Invoice amounts = ${inr(18000)} + ${inr(12000)} + ${inr(9000)} = ${rs(N2.totals.net)}, after deducting ${inr(2000)} and ${inr(3000)} as trade discount from the first two lists.`,
}));
const N3 = dayBook({ kind: 'sales', entries: [T('1', '1', 'A', 52000, 10), T('2', '2', 'B', 28000, 25), T('3', '3', 'C', 14000, 0)] });
same(N3.totals.net, 46800 + 21000 + 14000, 'n_sb_total');
QQ('n_sb_total', numQ({
  t: 2, d: 3, c: 'application', value: N3.totals.net,
  stem: 'Rewari Brassware, an imagined firm, made three credit sales in a month: list price ₹52,000 with trade discount 10%; list price ₹28,000 with trade discount 25%; and list price ₹14,000 without discount. The amount posted to the credit of its Sales A/c from the sales book is (in ₹)',
  sol: `Net sales = ${inr(46800)} + ${inr(21000)} + ${inr(14000)} = ${rs(N3.totals.net)}, because the discounts are ${inr(5200)} and ${inr(7000)}.`,
}));

// ================================================================ short answer, 2 marks
QQ('s2_pb_excluded', short({
  t: 2, d: 2, c: 'understanding', marks: 2,
  stem: 'Kozhikode Pens, an imagined firm, bought (i) goods for cash and (ii) a computer on credit. Why are neither entered in its purchases book, and where is each recorded?',
  model: '(i) A cash purchase is not a credit purchase, so it is recorded in the cash book.\n\n(ii) A computer is an asset and not goods bought for resale, so its credit purchase is recorded in the journal proper.',
  sol: 'One mark for each transaction with the correct book.',
  scheme: [['Cash purchase of goods: cash book', 1], ['Credit purchase of an asset: journal proper', 1]],
}));
QQ('s2_td_cd', short({
  t: 2, d: 3, c: 'analysis', marks: 2,
  stem: 'A supplier of Nanded Spices, an imagined firm, allows trade discount of 10% and, separately, a cash discount of 2% for payment within a week. State how each is treated when the purchase is entered in the books.',
  model: 'Trade discount is deducted from the list price on the invoice, so the purchases book shows only the net amount and no entry is made for the discount.\n\nCash discount depends on payment within the week; it is not deducted in the purchases book and, when it is earned, it is recorded in the cash book (and posted to the discount account).',
  sol: 'One mark for each discount.',
  scheme: [['Trade discount deducted before entry; no separate entry', 1], ['Cash discount not deducted in the purchases book; recorded at payment in the cash book', 1]],
}));
QQ('s2_columnar_uses', short({
  t: 2, d: 2, c: 'understanding', marks: 2,
  stem: 'Give two benefits of the columnar form of the sales book for an imagined garment trader who sells shirts, trousers and jackets.',
  model: '1. The month\'s credit sales of each class of goods are found at once from its column total.\n\n2. The column totals can be posted to separate sales accounts for shirts, trousers and jackets, so the trader learns which line sells best.',
  sol: 'One mark for each benefit.',
  scheme: [['Class-wise totals available directly', 1], ['Separate sales accounts posted from the column totals', 1]],
}));

// ================================================================ short answer, 3 marks
const B1 = dayBook({ kind: 'purchases', entries: [T('5 Sep', '412', 'Agra Leather Co.', 32000, 10), T('14 Sep', '419', 'Kanpur Soles', 18500, 20), T('23 Sep', '427', 'Agra Leather Co.', 21000, 5)] });
same(B1.totals.net, 28800 + 14800 + 19950, 's3_pb_simple');
QQ('s3_pb_simple', short({
  t: 2, d: 3, c: 'application', marks: 3,
  stem: 'Bhind Footwear, an imagined firm, bought goods on credit in September 2028: 5 Sep from Agra Leather Co., invoice 412, list price ₹32,000, trade discount 10%; 14 Sep from Kanpur Soles, invoice 419, list price ₹18,500, trade discount 20%; 23 Sep from Agra Leather Co., invoice 427, list price ₹21,000, trade discount 5%. Prepare the purchases book and show how its total and the invoices are posted.',
  model: `${B1.md}\n\nWorking: ${B1.workMd}\n\n${postMd(B1)}\n\nThe total ${rs(B1.totals.net)} is debited to Purchases A/c, and each invoice is credited to the account of its supplier.`,
  sol: 'Net amounts first, then the book, then the posting summary.',
  scheme: [['Each invoice entered at the net amount after trade discount (₹28,800, ₹14,800, ₹19,950)', 1], ['Book totalled correctly at ₹63,550', 1], ['Purchases A/c debited with the total; each supplier credited', 1]],
}));
const C1 = dayBook({ kind: 'sales', columns: ['Dinner sets', 'Glassware'], entries: [T('6 Jul', '61', 'Amar Gift House', { 'Dinner sets': 30000, Glassware: 12000 }, 10), T('19 Jul', '62', 'Bela Emporium', { Glassware: 25000 }, 20)] });
same(C1.totals.byCol[0], 27000, 's3_sb_columnar dinner');
same(C1.totals.byCol[1], 30800, 's3_sb_columnar glassware');
same(C1.totals.net, 57800, 's3_sb_columnar total');
QQ('s3_sb_columnar', short({
  t: 2, d: 3, c: 'application', marks: 3,
  stem: 'Chitradurga Crockery, an imagined firm, sold goods on credit in July 2028: 6 Jul to Amar Gift House, invoice 61, dinner sets at a list price of ₹30,000 and glassware at ₹12,000, trade discount 10%; 19 Jul to Bela Emporium, invoice 62, glassware at a list price of ₹25,000, trade discount 20%. Enter the sales in a columnar sales book with a column for each kind of goods.',
  model: `${C1.md}\n\nThe column totals ${rs(27000)} and ${rs(30800)} add up to the book total ${rs(C1.totals.net)}.`,
  sol: 'Net amounts by column, the invoice totals and the cross-check of the totals.',
  scheme: [['Net amounts under the right columns (₹27,000 and ₹10,800; ₹20,000)', 1], ['Invoice totals ₹37,800 and ₹20,000', 1], ['Column totals ₹27,000 and ₹30,800 agreeing with the grand total ₹57,800', 1]],
}));
const S1 = dayBook({ kind: 'sales', entries: [T('4 Aug', '301', 'Lalit Motors', 40000, 10), T('11 Aug', '304', 'Nandi Engines', 22000, 0), T('17 Aug', '307', 'Lalit Motors', 25000, 4), T('26 Aug', '310', 'Nandi Engines', 16000, 5), T('29 Aug', '312', 'Lalit Motors', 10000, 0)] });
const S1L = new Ledger().open('Lalit Motors A/c', 'dr', 18000, '1 Aug').fromBook(S1, '31 Aug');
const S1LM = S1L.show('Lalit Motors A/c', { close: '31 Aug', next: '1 Sep' });
same(S1LM.balance, 18000 + 36000 + 24000 + 10000, 's3_post_customer balance');
same(S1.totals.net, 36000 + 22000 + 24000 + 15200 + 10000, 's3_post_customer sales total');
QQ('s3_post_customer', short({
  t: 2, d: 3, c: 'application', marks: 3,
  stem: 'The sales book of Pratap Gears, an imagined firm, for August 2028 shows these credit sales (list price, trade discount): 4 Aug Lalit Motors, invoice 301, ₹40,000, 10%; 11 Aug Nandi Engines, invoice 304, ₹22,000, nil; 17 Aug Lalit Motors, invoice 307, ₹25,000, 4%; 26 Aug Nandi Engines, invoice 310, ₹16,000, 5%; 29 Aug Lalit Motors, invoice 312, ₹10,000, nil. Lalit Motors owed ₹18,000 on 1 August. (a) Write up and balance the account of Lalit Motors on 31 August [2]. (b) State the amount posted to the credit of the Sales A/c [1].',
  model: `**(a)**\n\n${S1LM.md}\n\n**(b)** The total of the sales book, **${rs(S1.totals.net)}**, is posted to the credit of the Sales A/c.`,
  sol: 'Opening balance and net invoices on the debit side, then the balance; the sales book total goes to Sales.',
  scheme: [['Opening balance ₹18,000 and the three net invoices ₹36,000, ₹24,000, ₹10,000 on the debit side', 1], ['Balance ₹88,000 carried down and brought down with equal totals', 1], ['Sales A/c credited with the book total ₹1,07,200', 1]],
}));

// ================================================================ long answer, 5 marks
const GROC = dayBook({
  kind: 'purchases',
  columns: ['Rice', 'Pulses', 'Oil'],
  entries: [
    T('2 Nov', '91', 'Godavari Rice Mills', { Rice: 60000 }, 10),
    T('8 Nov', '97', 'Dal Mandi Traders', { Pulses: 40000, Oil: 10000 }, 5),
    T('15 Nov', '103', 'Godavari Rice Mills', { Rice: 30000, Pulses: 20000 }, 10),
    T('21 Nov', '110', 'Sunrise Oils', { Oil: 35000 }, 20),
    T('29 Nov', '116', 'Dal Mandi Traders', { Pulses: 22000 }, 0),
  ],
});
same(GROC.totals.byCol[0], 81000, 'Medak rice');
same(GROC.totals.byCol[1], 38000 + 18000 + 22000, 'Medak pulses');
same(GROC.totals.byCol[2], 9500 + 28000, 'Medak oil');
same(GROC.totals.net, 81000 + 78000 + 37500, 'Medak total');
QQ('l5_pb_columnar', long({
  t: 2, d: 4, c: 'application', marks: 5,
  stem: 'Medak Grocers, an imagined firm, buys rice, pulses and oil. Its credit purchases in November 2028 (list price, trade discount) were: 2 Nov Godavari Rice Mills, invoice 91, rice ₹60,000, 10%; 8 Nov Dal Mandi Traders, invoice 97, pulses ₹40,000 and oil ₹10,000, 5%; 15 Nov Godavari Rice Mills, invoice 103, rice ₹30,000 and pulses ₹20,000, 10%; 21 Nov Sunrise Oils, invoice 110, oil ₹35,000, 20%; 29 Nov Dal Mandi Traders, invoice 116, pulses ₹22,000, nil. During the month it also bought rice for ₹12,000 in cash and a weighing machine for ₹14,000 on credit from Nashik Scales. (a) Prepare the columnar purchases book, leaving out transactions that do not belong in it [3]. (b) Show how the book is posted to the ledger [2].',
  model: `**(a)** The cash purchase of rice and the weighing machine are left out: the first goes to the cash book and the second to the journal proper.\n\n${GROC.md}\n\n**(b)**\n\n${postMd(GROC)}\n\nThe three column totals are debited to the Rice, Pulses and Oil Purchases accounts, and each invoice is credited to its supplier's account, so debits and credits are both ${rs(GROC.totals.net)}.`,
  sol: 'Leave out the cash purchase and the machine; net amounts by column; then the posting summary.',
  scheme: [['Cash purchase and weighing machine excluded from the book', 1], ['Net amounts under the correct columns for the five invoices', 1], ['Column totals ₹81,000, ₹78,000 and ₹37,500 agreeing with the total ₹1,96,500', 1], ['Rice, Pulses and Oil Purchases accounts debited with the column totals', 1], ['Three supplier accounts credited, debits equal to credits', 1]],
}));
const LE = dayBook({
  kind: 'sales',
  entries: [
    T('3 Dec', 'L11', 'Ratan Appliances', 48000, 10),
    T('9 Dec', 'L12', 'Sandhya Stores', 26000, 5),
    T('14 Dec', 'L13', 'Ratan Appliances', 15000, 0),
    T('22 Dec', 'L14', 'Tilak Agencies', 32000, 10),
    T('28 Dec', 'L15', 'Sandhya Stores', 18000, 5),
  ],
});
same(LE.totals.net, 43200 + 24700 + 15000 + 28800 + 17100, 'Lohit sales total');
const LEL = new Ledger().open('Ratan Appliances A/c', 'dr', 9500, '1 Dec').fromBook(LE, '31 Dec');
const LERA = LEL.show('Ratan Appliances A/c', { close: '31 Dec', next: '1 Jan' });
same(LERA.balance, 9500 + 43200 + 15000, 'Ratan Appliances balance');
QQ('l5_sb_ledger', long({
  t: 2, d: 4, c: 'application', marks: 5,
  stem: 'Lohit Electricals, an imagined firm, made these credit sales in December 2028 (list price, trade discount): 3 Dec Ratan Appliances, invoice L11, ₹48,000, 10%; 9 Dec Sandhya Stores, invoice L12, ₹26,000, 5%; 14 Dec Ratan Appliances, invoice L13, ₹15,000, nil; 22 Dec Tilak Agencies, invoice L14, ₹32,000, 10%; 28 Dec Sandhya Stores, invoice L15, ₹18,000, 5%. Ratan Appliances owed ₹9,500 on 1 December. (a) Prepare the sales book [2]. (b) Write up and balance the account of Ratan Appliances [2]. (c) State the entry for the book total in the Sales A/c [1].',
  model: `**(a)**\n\n${LE.md}\n\n**(b)**\n\n${LERA.md}\n\n**(c)** The total ${rs(LE.totals.net)} is posted to the credit of the Sales A/c, with the particulars "By Sundries as per Sales Book".`,
  sol: 'Net invoice amounts, the book total, the customer account and the Sales posting.',
  scheme: [['Net amounts ₹43,200, ₹24,700, ₹15,000, ₹28,800 and ₹17,100 entered', 1], ['Sales book totalled at ₹1,28,800', 1], ['Ratan Appliances: opening ₹9,500 and two invoices on the debit side', 1], ['Balance ₹67,700 carried down and brought down with equal totals', 1], ['Sales A/c credited with ₹1,28,800 as per the sales book', 1]],
}));
